                        cursor: 'pointer',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        gap: '8px'
                      }}
                    >
                      📊 View Analytics
                    </button>
                  </div>
                </>
              )}

              <button
                onClick={signOut}
                style={{
                  width: '100%',
                  background: '#ff4444',
                  color: 'white',
                  border: 'none',
                  borderRadius: '10px',
                  padding: '12px',
                  fontWeight: 'bold',
                  cursor: 'pointer',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  gap: '8px'
                }}
              >
                <LogOut size={16} />
                Sign Out
              </button>
            </div>
          </div>
        )}

    </div>
      )}

      {/* Shared Modals - Available in both modes */}
      {/* Individual Chat Modal */}
      {appState.activeChat && (
        <div style={{
          position: 'fixed',
          top: 'max(0px, env(safe-area-inset-top))',
          left: 0,
          right: 0,
          bottom: 0,
          background: 'white',
          zIndex: 1000,
          display: 'flex',
          flexDirection: 'column'
        }}>
          <div style={{
            padding: '15px 20px',
            background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
            color: 'white',
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center'
          }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
              <button
                onClick={() => updateState({ activeChat: null })}
                style={{
                  background: 'rgba(255,255,255,0.2)',
                  border: 'none',
                  borderRadius: '50%',
                  width: '44px',
                  height: '44px',
                  color: 'white',
                  cursor: 'pointer',
                  fontSize: '20px',
                  touchAction: 'manipulation',
                  WebkitTapHighlightColor: 'rgba(255,255,255,0.3)',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center'
                }}
              >
                ←
              </button>
              <div>
                <h3 style={{ margin: 0, fontSize: '18px' }}>{appState.activeChat.seller_name}</h3>
                <p style={{ margin: 0, fontSize: '14px', opacity: 0.8 }}>{appState.activeChat.item_title}</p>
              </div>
            </div>
            <button
              onClick={() => updateState({ showChats: false, activeChat: null })}
              style={{
                background: 'rgba(255,255,255,0.2)',
                border: 'none',
                borderRadius: '50%',
                width: '35px',
                height: '35px',
                color: 'white',
                cursor: 'pointer',
                fontSize: '18px'
              }}
            >
              ×
            </button>
          </div>

          <div style={{
            flex: 1,
            overflow: 'auto',
            padding: '20px',
            background: '#f8f9fa'
          }}>
            {appState.activeChat && appState.activeChat.messages && appState.activeChat.messages.map(message => (
              <div
                key={message.id}
                style={{
                  marginBottom: '15px',
                  display: 'flex',
                  justifyContent: message.sender_id === (user?.id || 'user123') ? 'flex-end' : 'flex-start'
                }}
              >
                <div style={{
                  maxWidth: '70%',
                  padding: '12px 16px',
                  borderRadius: '18px',
                  background: message.sender_id === (user?.id || 'user123') ? '#4CAF50' : 'white',
                  color: message.sender_id === (user?.id || 'user123') ? 'white' : '#333',
                  boxShadow: '0 2px 8px rgba(0,0,0,0.1)'
                }}>
                  <p style={{ margin: '0 0 5px 0', fontSize: '14px' }}>{message.text}</p>
                  <span style={{ 
                    fontSize: '12px', 
                    opacity: 0.7,
                    display: 'block',
                    textAlign: 'right'
                  }}>
                    {message.timestamp}
                  </span>
                </div>
              </div>
            ))}
          </div>

          <div style={{
            padding: '15px 20px',
            background: 'white',
            borderTop: '1px solid #eee',
            display: 'flex',
            gap: '10px',
            alignItems: 'center'
          }}>
            <input
              type="text"
              placeholder="Type a message..."
              value={appState.newMessage}
              onChange={(e) => updateState({ newMessage: e.target.value })}
              onKeyPress={(e) => {
                if (e.key === 'Enter' && appState.newMessage.trim()) {
                  const newMsg = {
                    id: `msg_${Date.now()}`,
                    sender_id: user?.id || 'user123',
                    sender_name: user?.username || 'You',
                    text: appState.newMessage.trim(),
                    timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
                  };

                  setAppState(prev => ({
                    ...prev,
                    newMessage: '',
                    activeChat: {
                      ...prev.activeChat,
                      messages: [...(prev.activeChat.messages || []), newMsg]
                    }
                  }));
                }
              }}
              style={{
                flex: 1,
                padding: '12px 16px',
                border: '1px solid #ddd',
                borderRadius: '25px',
                outline: 'none',
                fontSize: '14px'
              }}
            />
            <button
              onClick={() => {
                if (appState.newMessage.trim()) {
                  const newMsg = {
                    id: `msg_${Date.now()}`,
                    sender_id: user?.id || 'user123',
                    sender_name: user?.username || 'You',
                    text: appState.newMessage.trim(),
                    timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
                  };

                  setAppState(prev => ({
                    ...prev,
                    newMessage: '',
                    activeChat: {
                      ...prev.activeChat,
                      messages: [...(prev.activeChat.messages || []), newMsg]
                    }
                  }));
                }
              }}
              disabled={!appState.newMessage.trim()}
              style={{
                background: appState.newMessage.trim() ? '#4CAF50' : '#ddd',
                color: 'white',
                border: 'none',
                borderRadius: '50%',
                width: '45px',
                height: '45px',
                cursor: appState.newMessage.trim() ? 'pointer' : 'not-allowed',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center'
              }}
            >
              ➤
            </button>
          </div>
        </div>
      )}

      {/* Chat List Modal */}
      {appState.showChats && !appState.activeChat && (
        <div style={{
          position: 'fixed',
          top: 'max(0px, env(safe-area-inset-top))',
          left: 0,
          right: 0,
          bottom: 0,
          background: 'white',
          zIndex: 1000,
          display: 'flex',
          flexDirection: 'column'
        }}>
          <div style={{
            padding: '15px 20px',
            background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
            color: 'white',
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center'
          }}>
            <h2 style={{ margin: 0, fontSize: '20px' }}>💬 Messages</h2>
            <button
              onClick={() => updateState({ showChats: false })}
              style={{
                background: 'rgba(255,255,255,0.2)',
                border: 'none',
                borderRadius: '50%',
                width: '35px',
                height: '35px',
                color: 'white',
                cursor: 'pointer',
                fontSize: '18px'
              }}
            >
              ×
            </button>
          </div>

          <div style={{ flex: 1, overflow: 'auto' }}>
            {sampleChats.length === 0 ? (
              <div style={{
                padding: '60px 20px',
                textAlign: 'center',
                color: '#666'
              }}>
                <div style={{ fontSize: '48px', marginBottom: '20px' }}>💬</div>
                <h3 style={{ marginBottom: '10px' }}>No messages yet</h3>
                <p>Start swiping to connect with sellers!</p>
              </div>
            ) : (
              sampleChats.map((chat, i) => (
                <div
                  key={i}
                  onClick={() => updateState({ activeChat: chat })}
                  style={{
                    padding: '15px 20px',
                    borderBottom: '1px solid #eee',
                    cursor: 'pointer',
                    transition: 'background 0.2s ease'
                  }}
                  onMouseOver={(e) => e.currentTarget.style.background = '#f8f9fa'}
                  onMouseOut={(e) => e.currentTarget.style.background = 'white'}
                >
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                    <div>
                      <h4 style={{ margin: '0 0 5px 0', fontSize: '16px' }}>{chat.seller_name}</h4>
                      <p style={{ margin: '0 0 5px 0', fontSize: '14px', color: '#666' }}>{chat.item_title}</p>
                      <p style={{ margin: 0, fontSize: '13px', color: '#888' }}>
                        {chat.messages && chat.messages.length > 0 
                          ? chat.messages[chat.messages.length - 1].text
                          : 'Start a conversation...'}
                      </p>
                    </div>
                    <span style={{ fontSize: '12px', color: '#999' }}>
                      {chat.messages && chat.messages.length > 0 
                        ? chat.messages[chat.messages.length - 1].timestamp
                        : 'now'}
                    </span>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>
      )}

      {/* Profile Panel */}
      {appState.showProfile && (
        <div style={{
          position: 'fixed',
          top: 'max(0px, env(safe-area-inset-top))',
          right: 0,
          bottom: 0,
          width: '300px',
          background: 'white',
          boxShadow: '-5px 0 15px rgba(0,0,0,0.1)',
          zIndex: 1000,
          transform: 'translateX(0)',
          transition: 'transform 0.3s ease'
        }}>
          <div style={{ padding: '20px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
              <h3 style={{ margin: 0 }}>Profile</h3>
              <button
                onClick={() => updateState({ showProfile: false })}
                style={{
                  background: 'none',
                  border: 'none',
                  cursor: 'pointer',
                  fontSize: '20px',
                  touchAction: 'manipulation',
                  WebkitTapHighlightColor: 'rgba(255,255,255,0.3)',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center'
                }}
              >
                ×
              </button>
            </div>

            <div style={{ textAlign: 'center', marginBottom: '30px' }}>
              <img
                src={user?.avatar_url}
                alt="Profile"
                style={{
                  width: '80px',
                  height: '80px',
                  borderRadius: '50%',
                  marginBottom: '15px',
                  objectFit: 'cover'
                }}
              />
              <h4 style={{ margin: '0 0 5px 0' }}>{user?.username}</h4>
              <p style={{ color: '#666', margin: 0, fontSize: '14px' }}>{user?.email}</p>
            </div>

            {appState.currentMode === 'buyer' ? (
              <>
                <div style={{ marginBottom: '20px' }}>
                  <button
                    onClick={openSettings}
                    style={{
                      width: '100%',
                      background: '#667eea',
                      color: 'white',
                      border: 'none',
                      borderRadius: '10px',
                      padding: '12px',
                      fontWeight: 'bold',
                      cursor: 'pointer',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      gap: '8px'
                    }}
                  >
                    ⚙️ Search Preferences
                  </button>
                </div>

                <div style={{ marginBottom: '20px' }}>
                  <h5 style={{ marginBottom: '10px' }}>Daily Stats</h5>
                  <div style={{
                    background: '#f5f5f5',
                    borderRadius: '10px',
                    padding: '15px'
                  }}>
                    <p style={{ margin: '0 0 5px 0', fontSize: '14px' }}>
                      Interests today: {appState.dailySwipeCount}/{appState.maxDailySwipes}
                    </p>
                    <div style={{
                      background: '#ddd',
                      borderRadius: '5px',
                      height: '8px',
                      overflow: 'hidden'
                    }}>
                      <div style={{
                        background: '#4CAF50',
                        height: '100%',
                        width: `${(appState.dailySwipeCount / appState.maxDailySwipes) * 100}%`,
                        transition: 'width 0.3s ease'
                      }} />
                    </div>
                  </div>
                </div>
              </>
            ) : (
              <>
                <div style={{ marginBottom: '20px' }}>
                  <h5 style={{ marginBottom: '15px' }}>Seller Dashboard</h5>

                  <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
                    <div style={{
                      background: '#f5f5f5',
                      borderRadius: '10px',
                      padding: '15px',
                      textAlign: 'center'
                    }}>
                      <div style={{ fontSize: '24px', fontWeight: 'bold', color: '#667eea' }}>12</div>
                      <div style={{ fontSize: '12px', color: '#666' }}>Active Listings</div>
                    </div>

                    <div style={{
                      background: '#f5f5f5',
                      borderRadius: '10px',
                      padding: '15px',
                      textAlign: 'center'
                    }}>
                      <div style={{ fontSize: '24px', fontWeight: 'bold', color: '#4CAF50' }}>8</div>
                      <div style={{ fontSize: '12px', color: '#666' }}>Sales Completed</div>
                    </div>

                    <div style={{
                      background: '#f5f5f5',
                      borderRadius: '10px',
                      padding: '15px',
                      textAlign: 'center'
                    }}>
                      <div style={{ fontSize: '24px', fontWeight: 'bold', color: '#ff9800' }}>2.3h</div>
                      <div style={{ fontSize: '12px', color: '#666' }}>Avg Response Time</div>
                    </div>
                  </div>
                </div>
              </>
            )}

            <button
              onClick={signOut}
              style={{
                width: '100%',
                background: '#ff4444',
                color: 'white',
                border: 'none',
                borderRadius: '10px',
                padding: '12px',
                fontWeight: 'bold',
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                gap: '8px'
              }}
            >
              <LogOut size={16} />
              Sign Out
            </button>
          </div>
        </div>
      )}

      {/* Overlay for profile panel */}
      {appState.showProfile && (
        <div
          style={{
            position: 'fixed',
            top: 'max(0px, env(safe-area-inset-top))',
            left: 0,
            right: 0,
            bottom: 0,
            background: 'rgba(0,0,0,0.5)',
            zIndex: 999
          }}
          onClick={() => updateState({ showProfile: false })}
        />
      )}
    </>
  );
};

const App = () => (
  <AuthProvider>
    <SwipeMarketplace />
  </AuthProvider>
);

export default App;
